// Generated from docs/assets/leagues/*.png by task web-og-leagues.
// 128px transparent thumbnails; never fetch external artwork at request time.
const icons = {
  bronze: "data:image/png;base64,",
  silver: "data:image/png;base64,",
  gold: "data:image/png;base64,",
  platinum: "data:image/png;base64,",
  diamond: "data:image/png;base64,",
  master: "data:image/png;base64,",
  grandmaster: "data:image/png;base64,"
};

export function ogLeagueIcon(league) {
  return typeof league === "string" && Object.hasOwn(icons, league) ? icons[league] : "";
}
